    ["Advanced parameters (JSON)"] = "Gelişmiş parametreler (JSON)",
    ["Extra settings added to every reply, written as a JSON object, for example {example}. Use it for samplers that have no box above. A setting that has its own box above is refused. If a server refuses a setting, it is left out and the reply still comes."] = "Her yanıta eklenen ek ayarlar, JSON nesnesi olarak yazılır, örneğin {example}. Yukarıda kutusu olmayan örnekleyiciler için kullan. Yukarıda kendi kutusu olan bir ayar reddedilir. Bir sunucu bir ayarı reddederse o ayar dışarıda bırakılır ve yanıt yine gelir.",
    ["Mistral takes only the settings shown here. Top K, Min P and the advanced JSON are for Local AI and Custom models."] = "Mistral yalnızca burada gösterilen ayarları kabul eder. Top K, Min P ve gelişmiş JSON, Local AI ve özel modeller içindir.",
    ["Mistral does not take this setting."] = "Mistral bu ayarı kabul etmez.",
    ["That is not valid JSON."] = "Bu geçerli bir JSON değil.",
    ["This must be a JSON object, for example {example}."] = "Bir JSON nesnesi olmalı, örneğin {example}.",
    ["Too many keys. Keep {max} or fewer."] = "Çok fazla anahtar var. {max} veya daha az tut.",
    ["“{name}” is not a usable key name. Use letters, digits and underscores."] = "“{name}” kullanılabilir bir anahtar adı değil. Harf, rakam ve alt çizgi kullan.",
    ["“{name}” has its own setting in this form. Use that instead."] = "“{name}” bu formda kendi ayarına sahip. Bunun yerine onu kullan.",
    ["Use the Longest reply box for the length of a reply, not “{name}”."] = "Yanıt uzunluğu için En uzun yanıt kutusunu kullan, “{name}” değil.",
    ["“{name}” is set by the mod and cannot be changed here."] = "“{name}” mod tarafından ayarlanır ve burada değiştirilemez.",
    ["“{name}” needs a number, a text, true or false, or a list of those."] = "“{name}” bir sayı, bir metin, doğru ya da yanlış ya da bunların bir listesini gerektirir.",
    ["Longest character description, in characters"] = "En uzun karakter açıklaması (karakter)",
    ["Earlier turns kept"] = "Tutulan önceki turlar",
    ["Right-now sentence"] = "Anlık durum cümlesi",
    ["Notes for this turn"] = "Bu tur için notlar",
    ["That prompting option was not found."] = "Bu prompt seçeneği bulunamadı.",
    ["Keep at least one rule."] = "En az bir kural kalsın.",
    ["Rule {n} is empty. Write the rule or delete it."] = "{n}. kural boş. Kuralı yaz ya da sil.",
    ["Rule {n} is too long. Keep each one under {max} characters."] = "{n}. kural çok uzun. Her birini {max} karakterin altında tut.",
    ["The rules are too long together. Keep them under {max} characters in all."] = "Kurallar birlikte çok uzun. Hepsini toplam {max} karakterin altında tut.",
    ["This text is too long. Keep it under {max} characters."] = "Bu metin çok uzun. {max} karakterin altında tut.",
    ["This text cannot be empty."] = "Bu metin boş bırakılamaz.",
    ["Use a number from {min} to {max}."] = "{min} ile {max} arasında bir sayı kullan.",
    ["Too many stop texts. Keep {max} or fewer."] = "Çok fazla durdurma metni var. {max} ya da daha azını tut.",
    ["A stop text is too long. Keep each one under {max} characters."] = "Bir durdurma metni çok uzun. Her birini {max} karakterin altında tut.",
    ["{field}: {message}"] = "{field}: {message}",
    ["In use now"] = "Kullanımda",
    ["How each conversation option is told to answer. Every option has its own prompting. A change counts from the next reply, and nothing needs restarting."] = "Her konuşma seçeneğinin nasıl yanıt vereceği. Her seçeneğin kendi promptu vardır. Değişiklik bir sonraki yanıttan itibaren geçerli olur, yeniden başlatmaya gerek yoktur.",
    ["The facts the characters get from the game and a short list of safety filters cannot be edited here. Convai’s prompting lives on Convai’s side."] = "Karakterlerin oyundan aldığı gerçekler ve kısa bir güvenlik filtresi listesi burada düzenlenemez. Convai’nin promptu Convai tarafında tutulur.",
    ["Mistral and Local AI"] = "Mistral ve Local AI",
    ["Lite and Standard are the two Local AI model sizes. “Mature on” is used while Mature content is on."] = "Lite ve Standard, Local AI modelinin iki boyutudur. “Yetişkin içeriği açık” ifadesi, yetişkin içeriği açıkken kullanılır.",
    ["Your Custom models and APIs"] = "Özel modellerin ve API’lerin",
    ["A Custom model appears here once you choose Custom as the conversation provider and set a model."] = "Konuşma sağlayıcısı olarak Özel’i seçip bir model ayarladığında, özel model burada görünür.",
    ["From {min} to {max}."] = "{min} ile {max} arası.",
    ["Shipped: {value}"] = "Orijinal: {value}",
    ["Rule {n}"] = "Kural {n}",
    ["Rule {n}, for a speaker with a reply length of its own"] = "Kural {n}, kendi yanıt uzunluğu olan konuşmacı için",
    ["Rule {n}, for Mature content"] = "Kural {n}, yetişkin içeriği için",
    ["Move rule {n} up"] = "{n}. kuralı yukarı taşı",
    ["Move up"] = "Yukarı",
    ["Move rule {n} down"] = "{n}. kuralı aşağı taşı",
    ["Move down"] = "Aşağı",
    ["Delete rule {n}"] = "{n}. kuralı sil",
    ["Other versions of this rule"] = "Bu kuralın diğer sürümleri",
    ["Leave a version empty to use the rule text."] = "Kural metnini kullanmak için bir sürümü boş bırak.",
    ["For a speaker with a reply length of its own"] = "Kendi yanıt uzunluğu olan konuşmacı için",
    ["For Mature content"] = "Yetişkin içeriği için",
    ["Shipped: off"] = "Orijinal: kapalı",
    ["Shipped: the mod’s own limit"] = "Orijinal: modun kendi sınırı",
    ["before V’s words"] = "V’nin sözlerinden önce",
    ["after V’s words"] = "V’nin sözlerinden sonra",
    ["Repeat the “where you are” sentence right before V’s words"] = "“Neredesin” cümlesini V’nin sözlerinden hemen önce tekrarla",
    ["The notes for this turn go"] = "Bu turun notları şuraya gider",
    ["Output rules"] = "Çıktı kuralları",
    ["The numbered rules the model reads before every reply. Use {name} for the character’s name and {words} for the reply length of a speaker that has one."] = "Model her yanıttan önce okuduğu numaralı kurallar. Karakterin adı için {name}, varsa konuşmacının yanıt uzunluğu için {words} kullan.",
    ["Example replies"] = "Örnek yanıtlar",
    ["Replies shown to the model after the rules. A small model may copy them word for word, so add none, or keep them short and plain."] = "Kurallardan sonra modele gösterilen yanıtlar. Küçük bir model bunları kelimesi kelimesine kopyalayabilir; bu yüzden hiç ekleme ya da kısa ve sade tut.",
    ["Add an example reply"] = "Örnek yanıt ekle",
    ["An example reply"] = "Bir örnek yanıt",
    ["Example reply {n}"] = "Örnek yanıt {n}",
    ["Opening line"] = "Açılış satırı",
    ["The first line of the character text. Use {name} for the character’s name."] = "Karakter metninin ilk satırı. Karakterin adı için {name} kullan.",
    ["The last thing the model reads before it answers. Use {name} for the character’s name and {words} for the reply length. The Mature setting adds its own clause after it."] = "Model yanıt vermeden önce okuduğu son şey. Karakterin adı için {name}, yanıt uzunluğu için {words} kullan. Yetişkin içeriği ayarı bunun ardına kendi cümlesini ekler.",
    ["Section headings"] = "Bölüm başlıkları",
    ["The headings that mark each part of the prompt. Change the wording, not the order."] = "Promptun her bölümünü işaretleyen başlıklar. Metni değiştirebilirsin, sırasını değil.",
    ["Layout"] = "Yerleşim",
    ["Where some notes go in the prompt."] = "Promptta bazı notların nereye gideceği.",
    ["Sampling"] = "Örnekleme",
    ["How freely the model words its reply. Leave a box empty to use the shipped value."] = "Modelin yanıtını ne kadar serbestçe kurduğu. Kutuyu boş bırakırsan orijinal değer kullanılır.",
    ["Length limits"] = "Uzunluk sınırları",
    ["Shorten what the model reads, which makes replies faster. The mod’s own limits still apply, so these can only make things shorter."] = "Modelin okuduklarını kısalt; yanıtlar hızlanır. Modun kendi sınırları da geçerli kalır, bu yüzden bunlar yalnızca kısaltabilir.",
    ["Stop texts"] = "Stop metinleri",
    ["Mature layer"] = "Yetişkin katmanı",
    ["The crude, forward wording added while Mature content is on. The mod picks the explicit or the suggestive version of a line from what the loaded model allows, so edit the version your model uses. An emptied box leaves that line out. The adults-only line and the hard limits are always added last and cannot be edited."] = "Yetişkin içerik açıkken eklenen sert ve doğrudan ifadeler. Mod, yüklü modelin izin verdiğine göre bir satırın açık ya da ima içeren sürümünü seçer; bu yüzden modelinin kullandığı sürümü düzenle. Boşaltılan kutu o satırı çıkarır. Yalnızca yetişkinlere yönelik satır ve sabit sınırlar her zaman en sona eklenir ve düzenlenemez.",
    ["Speech line"] = "Konuşma satırı",
    ["Word bank"] = "Kelime bankası",
    ["Romance line"] = "Romantik satır",
    ["Closing clause"] = "Kapanış cümleciği",
    ["Tone line"] = "Ton satırı",
    ["Partner paragraph: affection and desire"] = "Partner paragrafı: sevgi ve arzu",
    ["Partner paragraph: nothing invented"] = "Partner paragrafı: uydurma yok",
    ["{part}, for models that allow explicit sex"] = "{part}, açık cinsel içeriğe izin veren modeller için",
    ["{part}, for models that keep sex suggestive"] = "{part}, sekssel ima yoluyla kalan modeller için",
    ["This option does not get the Mature layer."] = "Bu seçenek yetişkin katmanını almaz.",
    ["Mature layer and closing line, for models that allow explicit sex"] = "Yetişkin katmanı ve kapanış satırı, açık cinsel içeriğe izin veren modeller için",
    ["Mature layer and closing line, for models that keep sex suggestive"] = "Yetişkin katmanı ve kapanış satırı, sekssel ima yoluyla kalan modeller için",
    ["A reply ends when the model writes one of these. Line breaks count. Up to {max}."] = "Model bunlardan birini yazdığında yanıt biter. Satır sonları sayılır. En fazla {max}.",
    ["Add a stop text"] = "Durdurma metni ekle",
    ["A text that ends the reply"] = "Yanıtı bitiren bir metin",
    ["Stop text {n}"] = "Durdurma metni {n}",
    ["Preview"] = "Önizleme",
    ["The prompt text as the model would read it for a sample character. It follows your edits as you type, before you save."] = "Promptun, örnek bir karakter için modelin okuyacağı hâli. Kaydetmeden önce yazdıkça düzenlemelerini izler.",
    ["Sample character name"] = "Örnek karakterin adı",
    ["A speaker with a reply length of its own"] = "Kendi yanıt uzunluğu olan konuşmacı",
    ["Reply length in words"] = "Yanıt uzunluğu (kelime)",
    ["Mature content is on"] = "Yetişkin içeriği açık",
    ["The preview waits until the problems in the form are fixed."] = "Önizleme, formdaki sorunlar düzeltilene kadar bekler.",
    ["No example replies."] = "Örnek yanıt yok.",
    ["No closing line."] = "Kapanış satırı yok.",
    ["Go back to the shipped prompting for {name}? Your changes to this part are removed."] = "{name} için orijinal prompta dönülsün mü? Bu bölümdeki değişikliklerin kaldırılır.",
    ["Go back to the shipped prompting for {name}? All your changes to it are removed."] = "{name} için orijinal prompta dönülsün mü? Bu karaktere yaptığın tüm değişiklikler kaldırılır.",
    ["Back to the shipped prompting."] = "Orijinal prompta dön.",
    ["Prompting"] = "Prompt",
    ["Street reputation"] = "Sokak itibarı",
    ["Gangs, the NCPD, corporations and the locals of each district remember what V did: Street Cred, choices in jobs, fights, crimes the police saw and how you treat people. It shapes their greeting, trust and help.\n\nOnly ordinary people, never named or story characters. It changes their words, nothing in the game."] = "Çeteler, NCPD, şirketler ve her bölgenin halkı V’nin yaptıklarını hatırlar: Street Cred, işlerdeki seçimler, kavgalar, polisin gördüğü suçlar ve insanlara nasıl davrandığın. Selam, güven ve yardım buna göre olur.\n\nYalnızca sıradan insanlar, asla isimli veya hikâye karakterleri. Sözlerini değiştirir, oyunda hiçbir şeyi değil.",
    ["NPCs react to threats and commands"] = "NPC’ler tehditlere ve emirlere tepki verir",
    ["Ordinary people you threaten run, cower or fight back, as their kind would: gang members and guards use their fists for an insult and their weapons for a death threat.\n\nThey may also do what you tell them, if they would: get down, stop, or get out of the vehicle.\n\nOnly ordinary people, never named or story characters, and never during scenes, quests or fights."] = "Tehdit ettiğin sıradan insanlar, kendi yapılarına göre kaçar, sinip korkar ya da karşılık verir: çete üyeleri ve korumalar hakarete yumrukla, ölüm tehdidine silahla karşılık verir.\n\nYapacaklarsa söylediğini de yapabilirler: yere yatmak, durmak ya da araçtan inmek.\n\nYalnızca sıradan insanlar, asla isimli ya da hikâye karakterleri değil, ve asla sahneler, görevler ya da çatışmalar sırasında değil.",
    ["Voice language"] = "Ses dili",
    ["English"] = "İngilizce",
    ["Automatic"] = "Otomatik",
    ["Polish"] = "Lehçe",
    ["Russian"] = "Rusça",
    ["Ukrainian"] = "Ukraynaca",
    ["Turkish"] = "Türkçe",
    ["Czech"] = "Çekçe",
    ["Hungarian"] = "Macarca",
    ["Japanese"] = "Japonca",
    ["Korean"] = "Korece",
    ["Chinese"] = "Çince",
    ["Choose one of the listed reply languages."] = "Listelenen yanıt dillerinden birini seçin.",
    ["No speech was heard. Hold the talk key while you speak."] = "Konuşma algılanmadı. Konuşurken ses tuşuna basılı tut.",
    ["Voice activation"] = "Sesle etkinleştirme",
    ["Voice activation could not open the microphone. Check your Windows input device."] = "Sesle etkinleştirme mikrofonu açamadı. Windows giriş aygıtını kontrol et.",
    ["Voice input could not reach Convai. Hold the voice key again, or type."] = "Sesli giriş Convai’ye ulaşamadı. Ses tuşuna yeniden basılı tut ya da yaz.",
    ["Talk without a key. While you face a character or a companion is near, the mod listens and answers when you pause for about a second.\n\nNever during the game’s own scenes or choices, or while a character speaks. Nothing leaves your PC unless speech is heard. Headphones work best, but a Bluetooth headset’s microphone drops it to call quality while this listens."] = "Bir tuşa basılı tutmadan konuş. Bir karaktere dönükken ya da yakında bir yoldaş varken mod seni dinler ve yaklaşık bir saniye duraksadığında yanıt verir.\n\nOyunun kendi sahnelerinde, diyalog seçimlerinde ya da bir karakter konuşurken asla dinlemez. Konuşma duyulmadıkça PC’nden hiçbir şey çıkmaz. En iyisi kulaklık; Bluetooth kulaklığın mikrofonu dinlerken çağrı kalitesine geçirir.",
    ["Opening microphone…"] = "Mikrofon açılıyor…",
    ["Speak now"] = "Şimdi konuş",
    ["Type in the search box to find a model by name or record, for example “rita wheeler”. A part of a word is enough."] = "Bir modeli ada veya kayda göre bulmak için arama kutusuna yaz, örneğin “rita wheeler”. Kelimenin bir kısmı yeterli.",
    ["Content packs"] = "İçerik paketleri",
    ["Add-ons that change how the characters talk."] = "Karakterlerin konuşma biçimini değiştiren eklentiler.",
    ["Turns the content pack {name} on or off. A pack changes how the characters talk. Its prompt changes work with Mistral, Local AI and Custom. On Convai its world rules and its own Convai characters apply. A switch counts from the next reply, new names after a restart."] = "{name} içerik paketini açar veya kapatır. Bir paket karakterlerin konuşma biçimini değiştirir. Prompt değişiklikleri Mistral, Local AI ve Özel ile çalışır. Convai’de paketin dünya kuralları ve kendi Convai karakterleri geçerlidir. Değişiklik bir sonraki yanıttan itibaren geçerli olur, yeni adlar yeniden başlatmadan sonra.",
    ["Content packs add rules after yours. You cannot edit them here: turn a pack off under Settings > Content packs in the game."] = "İçerik paketleri kurallarınızdan sonra kurallar ekler. Bunları burada düzenleyemezsiniz: oyunda Ayarlar > İçerik paketleri bölümünden bir paketi kapatın.",
    ["From the content pack {name}"] = "{name} içerik paketinden",
    ["Content packs that change this prompt: {names}. Your own changes stay on top of theirs, and Reset to default goes back to the pack’s wording."] = "Bu prompt’u değiştiren içerik paketleri: {names}. Kendi değişiklikleriniz onların üstünde kalır; Varsayılana sıfırla ise paketin metnine döndürür.",
    ["Memory in use"] = "Kullanımdaki hafıza",
    ["Normal memory"] = "Normal hafıza",
    ["Forget memories clears only the memory shown here. The other memory stays as it is."] = "Anıları unut yalnızca burada gösterilen hafızayı temizler. Diğer hafıza olduğu gibi kalır.",
    ["This clears the memory in use: {memory}."] = "Bu, kullanımdaki hafızayı temizler: {memory}.",
    ["Backspace"] = "Backspace",
    ["Cancelled."] = "İptal edildi.",
    ["Caps lock"] = "Caps Lock",
    ["Choose a key or a controller button."] = "Bir tuş ya da denetleyici düğmesi seç.",
    ["Choose the keys and controller buttons for talking by voice or text, the group chats and the Companion Manager. They work at once."] = "Sesle ya da yazıyla konuşmak, grup sohbetleri ve Yoldaş Yöneticisi için tuşları ve denetleyici düğmelerini seç. Hemen çalışırlar.",
    ["Choose the keys and controller buttons for the mod’s actions. Press Set, then the key or button you want. Esc or B cancels. A change works at once, and the keys you set in Cyber Engine Tweaks keep working. Pick keys the game does not already use."] = "Modun eylemleri için tuşları ve denetleyici düğmelerini seç. Ayarla’ya bas, sonra istediğin tuşa ya da düğmeye bas. Esc ya da B iptal eder. Değişiklik hemen çalışır, Cyber Engine Tweaks’te ayarladığın tuşlar da çalışmaya devam eder. Oyunun zaten kullanmadığı tuşları seç.",
    ["Controller {button}"] = "Denetleyici: {button}",
    ["D-pad down"] = "Yön düğmesi aşağı",
    ["D-pad left"] = "Yön düğmesi sol",
    ["D-pad right"] = "Yön düğmesi sağ",
    ["D-pad up"] = "Yön düğmesi yukarı",
    ["Down arrow"] = "Aşağı ok",
    ["End"] = "End",
    ["Enter"] = "Enter",
    ["Group text chat"] = "Grup yazılı sohbet",
    ["Group voice chat"] = "Grup sesli sohbet",
    ["Hold it to talk to the characters around you at once, and let go to send. Facing nobody, you talk to the first member of your party and two others from it."] = "Yakınındaki tüm karakterlere aynı anda konuşmak için basılı tut, göndermek için bırak. Kimseye bakmıyorsan grubunun ilk üyesiyle ve gruptan iki kişiyle konuşursun.",
    ["Hold it to talk to Johnny, the voice in your head, wherever you face, and let go to send. It needs Johnny in your head turned on in Settings."] = "Kafandaki ses olan Johnny ile konuşmak için basılı tut, nereye bakarsan bak, ve göndermek için bırak. Ayarlar’da Kafanda Johnny açık olmalı.",
    ["Hold the key or button while you speak and let go to send, like the Cyber Engine Tweaks talk key. Facing nobody, you talk to the first member of your party."] = "Konuşurken tuşu ya da düğmeyi basılı tut, göndermek için bırak. Bu, Cyber Engine Tweaks’teki konuşma tuşuyla aynı şekilde çalışır. Kimseye bakmıyorsan grubunun ilk üyesiyle konuşursun.",
    ["Home"] = "Home",
    ["Insert"] = "Insert",
    ["Key bindings"] = "Tuş atamaları",
    ["Key bindings need Codeware, and this game does not have it. Open Help for what is missing."] = "Tuş atamaları için Codeware gerekir, bu oyunda ise yok. Neyin eksik olduğunu görmek için Yardım’ı aç.",
    ["Key or button"] = "Tuş ya da düğme",
    ["Left arrow"] = "Sol ok",
    ["Menu"] = "Menü",
    ["No key was pressed, so nothing changed."] = "Hiçbir tuşa basılmadı, bu yüzden bir şey değişmedi.",
    ["Not available"] = "Kullanılamıyor",
    ["Not set"] = "Ayarlanmadı",
    ["Num lock"] = "Num Lock",
    ["Page down"] = "Page Down",
    ["Page up"] = "Page Up",
    ["Pause"] = "Pause",
    ["Press it, then the key or controller button you want. Esc or B cancels. It works at once."] = "Buna bas, sonra istediğin tuşa ya da denetleyici düğmesine bas. Esc ya da B iptal eder. Hemen çalışır.",
    ["Press it to open the Companion Manager while you play."] = "Oynarken Yoldaş Yöneticisi’ni açmak için bas.",
    ["Press it to type to the character you face. Facing nobody, you type to the first member of your party."] = "Karşında duran karaktere yazmak için bas. Kimseye bakmıyorsan grubunun ilk üyesine yazarsın.",
    ["Press it to type to Johnny, the voice in your head, wherever you face. It needs Johnny in your head turned on in Settings."] = "Kafandaki ses olan Johnny’ye, nereye bakarsan bak, yazmak için bas. Ayarlar’da Kafanda Johnny açık olmalı.",
    ["Press it to type to the characters around you at once. Facing nobody, you type to the first member of your party and two others from it."] = "Yakınındaki tüm karakterlere aynı anda yazmak için bas. Kimseye bakmıyorsan grubunun ilk üyesine ve gruptan iki kişiye yazarsın.",
    ["Press the key or controller button for {action}. Esc or B cancels."] = "{action} için tuşa ya da denetleyici düğmesine bas. Esc ya da B iptal eder.",
    ["Print screen"] = "Print Screen",
    ["Remove the key or button you set here."] = "Burada ayarladığın tuşu ya da düğmeyi kaldır.",
    ["Right arrow"] = "Sağ ok",
    ["Scroll lock"] = "Scroll Lock",
    ["Space"] = "Boşluk",
    ["Tab"] = "Tab",
    ["Talk by text"] = "Yazıyla konuş",
    ["Talk by voice"] = "Sesle konuş",
    ["Talk to Johnny by text"] = "Johnny ile yazıyla konuş",
    ["Talk to Johnny by voice"] = "Johnny ile sesle konuş",
    ["That key is already used for another action."] = "Bu tuş zaten başka bir eylem için kullanılıyor.",
    ["The mod’s key bindings could not be loaded. Open Help for what is wrong."] = "Modun tuş atamaları yüklenemedi. Neyin yanlış olduğunu görmek için Yardım’ı aç.",
    ["The mod’s scripts did not load, so no key can be set. Open Help for what is wrong."] = "Modun betikleri yüklenmedi, bu yüzden hiçbir tuş ayarlanamaz. Neyin yanlış olduğunu görmek için Yardım’ı aç.",
    ["Up arrow"] = "Yukarı ok",
    ["View"] = "Görünüm",
    ["{action} cleared."] = "{action} temizlendi.",
    ["{action} is set to {key}."] = "{action} şuna ayarlandı: {key}.",
    ["{key} is already used for {other}. Choose another."] = "{key} zaten {other} için kullanılıyor. Başka bir tuş seç.",
    ["10 minutes"] = "10 dakika",
    ["2 minutes"] = "2 dakika",
    ["5 minutes"] = "5 dakika",
    ["Cancel this meeting. She is not told."] = "Buluşmayı iptal et. Ona haber verilmez.",
    ["Car"] = "Araba",
    ["Choose how long she waits."] = "Ne kadar bekleyeceğini seç.",
    ["Choose how she arrives."] = "Nasıl geleceğini seç.",
    ["Choose one of the listed options."] = "Listelenen seçeneklerden birini seç.",
    ["Choose when she arrives."] = "Ne zaman geleceğini seç.",
    ["Companions travel to you when you invite them: they walk or drive in, text you, wait, and remember if you never come.\n\nOff by default."] = "Davet ettiğinde yoldaşlar sana gelir: yürür ya da arabayla gelir, mesaj atar, bekler ve hiç gelmezsen bunu hatırlar.\n\nVarsayılan olarak kapalı.",
    ["Fine. Call me when you know what you want."] = "Tamam. Ne istediğine karar verince ara.",
    ["How long she waits"] = "Ne kadar bekleyeceği",
    ["How long she waits for you after arriving right now. After a timed arrival she waits as long as the delay you chose. The wait stops while you are in a fight, a scene or a menu."] = "Şu an varınca sen gelene kadar ne kadar bekleyecek. Zamanlanmış gelişten sonra seçilen gecikme kadar bekler. Savaşta, sahnede ya da menüdeyken bekleme durur.",
    ["How she arrives"] = "Nasıl geleceği",
    ["I waited {minutes} minutes at {place} and you never showed. Forget it."] = "{place} yerinde {minutes} dakika bekledim, sen hiç gelmedin. Boş ver.",
    ["I'm here at {place}. Where are you?"] = "{place} yerindeyim. Neredesin?",
    ["Immersive invitations"] = "Sürükleyici davetler",
    ["In 10 minutes"] = "10 dakikada",
    ["In 2 minutes"] = "2 dakikada",
    ["In 5 minutes"] = "5 dakikada",
    ["Invite a companion and she really travels to you: she appears out of sight, walks or drives in, texts you when she is there and waits for you."] = "Bir yoldaşı davet et, gerçekten sana gelsin: görüş alanının dışında belirir, yürür ya da arabayla gelir, orada olunca sana yazar ve seni bekler.",
    ["Meet at my waypoint when I ask"] = "İstenince yol noktama buluş",
    ["Off: Invite brings a companion to your side at once.\n\nOn: a companion you invite, by the Invite button, the Contacts tab or a text, travels to you and arrives after the time you choose here. She texts you when she is there, waits, and leaves angry (and remembers it) if you never come."] = "Kapalı: Davet et, bir yoldaşı hemen yanına getirir.\n\nAçık: Davet et düğmesi, Kişiler sekmesi ya da bir mesajla davet ettiğin yoldaş sana gelir ve burada seçtiğin süreden sonra varır. Orada olunca yazar, bekler ve hiç gelmezsen kızgın şekilde ayrılır (ve bunu hatırlar).",
    ["Right now"] = "Hemen",
    ["Right now: she is on her way as soon as she is ready.\n\nIn 2, 5 or 10 minutes: real minutes of play, so she arrives at that time. She then waits as long as that delay."] = "Hemen: hazır olur olmaz yola çıkar.\n\n2, 5 ya da 10 dakikada: gerçek oyun dakikaları, yani o zamanda varır. Sonra o gecikme kadar bekler.",
    ["She texts you"] = "Sana mesaj atar",
    ["She texts you when she arrives, when you cancel and when she gives up. Off: no texts (she still remembers being stood up)."] = "Vardığında, iptal ettiğinde ve pes ettiğinde sana yazar. Kapalı: mesaj yok (yine de bekletildiğini hatırlar).",
    ["Something came up and I can't make it. Sorry."] = "Bir şey çıktı, gelemeyeceğim. Kusura bakma.",
    ["Walk"] = "Yaya",
    ["Walk: she appears out of your sight and walks to you.\n\nCar: when a road is near she drives in, stops on the road, gets out and walks the rest. Without a road she walks. The car stays near for a ride, and is removed when she leaves your group or you both go far from it."] = "Yaya: görüş alanının dışında belirir ve sana yürür.\n\nAraba: yakında bir yol varsa arabayla gelir, yolda durur, iner ve kalan yolu yürür. Yol yoksa yürür. Araba yolculuk için yakında kalır ve grubundan ayrılırsa ya da ikiniz de ondan uzaklaşırsanız kaldırılır.",
    ["When she arrives"] = "Geldiğinde",
    ["When you ask her to come to your waypoint and a map pin is set, she goes there and says so. Off: she always comes to where you are."] = "Yol noktanıza gelmesini istediğinde ve haritada bir işaret varsa oraya gider ve bunu söyler. Kapalı: her zaman bulunduğun yere gelir.",
    ["Your position cannot be read yet."] = "Konumun henüz okunamıyor.",
    ["on her way"] = "yolda",
    ["the meeting spot"] = "buluşma yeri",
    ["waiting at {place}"] = "{place} yerinde bekliyor",
    ["{name} is already on the way."] = "{name} zaten yolda.",
    ["{name} is on her way."] = "{name} yolda.",
    ["{name} is on her way. About {minutes} minutes."] = "{name} yolda. Yaklaşık {minutes} dakika.",
    ["{name} · {state}"] = "{name} · {state}",
    ["{name}: Good to see you. Let us go."] = "{name}: Seni görmek güzel. Hadi gidelim.",
    ["Corpo Plaza"] = "Corpo Plaza",
    ["Heywood Glen"] = "Heywood Glen",
    ["Megabuilding H10"] = "Megabuilding H10",
    ["Move out"] = "Evden çıksın",
    ["That companion is not available."] = "Bu yoldaş müsait değil.",
    ["Watson Northside"] = "Watson Northside",
    ["Westbrook Japantown"] = "Westbrook Japantown",
    ["You do not have that apartment."] = "Bu daireye sahip değilsin.",
    ["at home"] = "evde",
    ["out"] = "dışarıda",
    ["with you"] = "seninle",
    ["{count} more housemates"] = "{count} ev arkadaşı daha",
    ["{name} has moved out."] = "{name} evden taşındı.",
    ["{name} is back at home."] = "{name} yeniden evde.",
    ["{name} joins you."] = "{name} sana katılıyor.",
    ["{name} moves into {apartment}."] = "{name}, {apartment} dairesine taşınıyor.",
    ["{name} now lives in {apartment} and stays in your party until sent home."] = "{name} artık {apartment} dairesinde yaşıyor ve eve gönderilene kadar grubunda kalıyor.",
    ["{name} stops living at your place. She stays as she is otherwise."] = "{name} artık senin yanında kalmıyor. Bunun dışında her şey aynı kalır.",
    ["{name} · lives in {apartment} · {state}"] = "{name} · {apartment} dairesinde yaşıyor · {state}",
    ["Companions change outfits"] = "Yoldaşlar kıyafet değiştirir",
    ["Your party’s companions change outfits now and then: another look by day and by night, and casual clothes at home, where the character has them.\n\nOnly out of your sight, never in front of you, and only for your party’s own copies, never the game’s own characters. Turning this off keeps what they wear now."] = "Ekibindeki yoldaşlar ara sıra kıyafetlerini değiştirir: gündüz ve gece için farklı bir görünüm, karakterin sahip olduğu durumlarda evde rahat kıyafetler.\n\nYalnızca görüş alanının dışındayken, asla tam önünde değil ve yalnızca ekibinin kendi kopyaları için, oyunun kendi karakterleri için asla değil. Bu seçeneği kapatmak, şu an giydikleri kıyafetlerde kalmalarını sağlar.",
    ["Choose how often companions speak up."] = "Yoldaşların ne sıklıkta söz alacağını seç.",
    ["Companions speak up"] = "Yoldaşlar konuşur",
    ["How V is doing according to other mods, when they are installed: Dark Future’s tiredness, hunger, thirst, nerve and addictions, for example. Also what V visibly wears while an Equipment-EX outfit is on, so characters describe the outfit and not the clothes it hides.\n\nOff by default. Off: it is not sent, and nothing is read from those mods."] = "Diğer modlar kuruluysa, onların bildirdiğine göre V’nin durumu: örneğin Dark Future’ın yorgunluk, açlık, susuzluk, sinir ve bağımlılık değerleri. Ayrıca bir Equipment-EX kıyafeti etkinken V’nin görünür şekilde ne giydiği de gönderilir, böylece karakterler kıyafeti anlatır, onun gizlediği giysileri değil.\n\nVarsayılan olarak kapalı. Kapalı: hiçbir şey gönderilmez ve bu modlardan hiçbir şey okunmaz.",
    ["How long it has been since V last talked to this character, in the game and in real days: since last night, or days ago. Said only when the gap is long enough to matter, and not again in the same conversation.\n\nOff: it is not sent, and the mod stops reading the game clock for it."] = "V’nin bu karakterle en son ne zaman konuştuğundan bu yana oyunda ve gerçek günlerde ne kadar zaman geçtiği: dün geceden beri ya da günler önce. Yalnızca aradaki süre önemli olacak kadar uzunsa söylenir ve aynı konuşmada bir daha söylenmez.\n\nKapalı: hiçbir şey gönderilmez ve mod bunun için oyun saatini okumayı bırakır.",
    ["Music and TV"] = "Müzik ve TV",
    ["Other mods’ state"] = "Diğer modların durumu",
    ["Speaks up normally"] = "Normalde konuşur",
    ["The song playing on the car radio while V rides with the character, or on V’s pocket radio, and what is on a TV near V.\n\nOff: it is not sent, and the mod stops reading it from the game."] = "V karakterle birlikte araçta yolculuk yaparken araba radyosunda çalan şarkı, ya da V’nin cep radyosunda çalan şarkı ve V’nin yakınındaki bir televizyonda ne olduğu.\n\nKapalı: hiçbir şey gönderilmez ve mod bunu oyundan okumayı bırakır.",
    ["Time since last talk"] = "Son konuşmadan bu yana geçen süre",
    ["Companions in your party sometimes start talking on their own: now and then at a calm moment, and after a scene or a conversation they were part of. Never during fights, scenes, calls or menus.\n\nRarely: about 2 an hour. Normally: about 4. Often: about 6.\n\nWith Johnny speaking up too, the rates add up and they take turns."] = "Gruptaki yoldaşlar bazen kendiliğinden konuşmaya başlar: zaman zaman sakin bir anda ve katıldıkları bir sahneden ya da konuşmadan sonra. Asla çatışmalar, sahneler, aramalar ya da menüler sırasında değil.\n\nNadiren: oyun saati başına yaklaşık 2. Normalde: yaklaşık 4. Sık: yaklaşık 6.\n\nJohnny de konuşuyorsa iki sıklık toplanır ve konuşanlar sırayla konuşur.",
    ["Johnny Silverhand answers the Talk to Johnny keys, as the voice in V’s head, once the story has him there. Give Talk to Johnny a key on the Key bindings page: none is set by default.\n\nOn: he answers when you talk to him. Rarely: he also speaks up on his own, about 2 an hour. Normally: about 4. Often: about 6.\n\nWith companions speaking up too, the rates add up and they take turns."] = "Johnny Silverhand, V’nin kafasındaki ses olarak, hikâye onu oraya koyunca „Johnny ile konuş“ tuşlarına yanıt verir. Tuş atamaları sayfasında bu işleve bir tuş atayın: varsayılan olarak yok.\n\nAçık: ona konuşulduğunda yanıt verir. Nadiren: kendiliğinden de konuşur, saatte yaklaşık 2. Normalde: yaklaşık 4. Sık: yaklaşık 6.\n\nYoldaşlar da konuşursa oranlar toplanır ve sırayla konuşurlar.",
    ["Choose which live game info the characters are told, such as location, time, weather, company, health, money, gear, quests, music and TV, and other mods’ state.\n\nAll on by default except other mods’ state, which is off. An off kind is not sent to any conversation provider."] = "Karakterlere iletilecek canlı oyun bilgilerini seç: konum, saat, hava durumu, yoldaşlar, sağlık, para, ekipman, görevler, müzik ve TV ile diğer modların durumu gibi.\n\nVarsayılan olarak her şey açıktır, yalnızca diğer modların durumu kapalıdır. Kapalı bir tür hiçbir konuşma sağlayıcısına gönderilmez.",
    ["Housemates"] = "Ev arkadaşları",
    ["Housemates talk to each other"] = "Ev arkadaşları birbiriyle konuşur",
    ["When two or more housemates are home with you, they talk to each other now and then."] = "İki ya da daha fazla ev arkadaşı seninle evdeyken ara sıra birbirleriyle konuşurlar.",
    ["Characters you tell they can stay at your place move into your apartments and live there."] = "Evinde kalabileceklerini söylediğin karakterler dairelerine taşınır ve orada yaşar.",
    ["Characters you tell they can stay at your place move into your apartments and live there.\n\nOff by default."] = "Evinde kalabileceklerini söylediğin karakterler dairelerine taşınır ve orada yaşar.\n\nVarsayılan olarak kapalı.",
    ["On: characters you tell they can stay at your place move into your apartments and live there, and you can call them along.\n\nOff: nothing of this runs. Turning it off removes them from your apartments but remembers who lived there, so turning it on brings them back."] = "Açık: evinde kalabileceklerini söylediğin karakterler dairelerine taşınır ve orada yaşar, onları yanında da götürebilirsin.\n\nKapalı: bunların hiçbiri çalışmaz. Kapatınca dairelerinden çıkarlar ama orada kimin yaşadığı hatırlanır, böylece açınca geri gelirler.",
    ["OmniVoice Python"] = "OmniVoice Python",
    ["OmniVoice’s code could not load in it"] = "OmniVoice kodu yüklenemedi",
    ["PyTorch is not installed in it"] = "PyTorch içinde yüklü değildir",
    ["Your own Python (omni-python.txt) is being tested. Open this page again in a minute."] = "Kendi Python'unuz (omni-python.txt) test ediliyor. Bu sayfayı bir dakika içinde yeniden açın.",
    ["Your own Python (omni-python.txt) is tested when OmniVoice starts or when this page checks again."] = "Kendi Python'unuz (omni-python.txt) OmniVoice başlatıldığında veya bu sayfa yeniden kontrol edildiğinde test edilir.",
    ["Your own Python (omni-python.txt) runs OmniVoice with {backend} on {card}. Experimental."] = "Kendi Python'unuz (omni-python.txt) OmniVoice'i {backend} ile {card} üzerinde çalıştırır. Deneyseldir.",
    ["Your own Python (omni-python.txt) was not used: {reason}. OmniVoice uses the Runtime’s Python, which needs an NVIDIA card."] = "Kendi Python'unuz (omni-python.txt) kullanılmadı: {reason}. OmniVoice, Runtime'ın Python'unu kullanır, bu da bir NVIDIA kartı gerektirir.",
    ["a test on the graphics card failed"] = "grafik kartında bir test başarısız oldu",
    ["it did not start or did not answer in time"] = "başlamadı veya zamanında yanıt vermedi",
    ["its PyTorch finds no graphics card (no CUDA or ROCm)"] = "onun PyTorch grafik kartı bulamıyor (CUDA veya ROCm yok)",
    ["the OmniVoice pack is not installed"] = "OmniVoice paketi yüklü değildir",
    ["the file does not name a python.exe that exists"] = "dosya var olan bir python.exe adını taşımıyor",
    ["the module {module} is missing in it"] = "modül {module} içinde eksiktir",
    ["1 minute"] = "1 dakika",
    ["2 people"] = "2 kişi",
    ["3 people"] = "3 kişi",
    ["4 people"] = "4 kişi",
    ["Every character who lives at your place moves out at once, from every apartment. Party members who do not live there are not touched. A housemate who is with you stays in your party."] = "Senin yanında yaşayan her karakter bir anda, her daireden taşınır. Orada yaşamayan ekip üyeleri etkilenmez. Seninle olan bir ev arkadaşı ekibinde kalır.",
    ["Evict"] = "Evden çıksın",
    ["Evict all housemates"] = "Tüm ev arkadaşlarını çıkart",
    ["Housemates in one chat"] = "Bir sohbette ev arkadaşları",
    ["Housemates moved out: {count}"] = "Ev arkadaşları taşındı: {count}",
    ["How long the housemates stay quiet after a chat before they may start another. The Companions speak up setting still limits how many chats come in an hour."] = "Ev arkadaşlarının bir sohbetten sonra sessiz kalma süresi, başka bir tane başlamadan önce. Yoldaşlar konuşur ayarı, saatte kaç sohbet geleceğini sınırlandırır.",
    ["How many housemates join one chat when that many are home near each other. They speak one at a time. With fewer at home, the chat is as big as it can be."] = "O kadar ev arkadaşı evde birbirlerine yakın olduğunda bir sohbete kaç kişi katılır. Birer birer konuşurlar. Evde daha az varsa, sohbet olabildiğince büyük olur.",
    ["Move-in apartment"] = "Taşınma dairesi",
    ["Nobody lives at your place."] = "Senin yerine kimse yaşamıyor.",
    ["Pause between chats"] = "Sohbetler arasında duraklatma",
    ["Where a character moves in when you say she can stay but name no apartment and you are not standing in one of yours.\n\nAsk me: she asks which one. Otherwise she takes the apartment you pick here. Only the apartments you own are listed."] = "Kalabileceğini söyledin ama daire adı vermedin ve senin dairelerinden birinde durmuyorken bir karakterin taşındığı yer.\n\nBana sor: hangisi olduğunu sorar. Aksi halde burada seçtiğin dairesini alır. Yalnızca sahip olduğun daireler listelenir.",
    ["Ask me"] = "Bana sor",
    ["Could not start"] = "Başlatılamadı",
    ["Did not start"] = "Başlamadı",
    ["If the folder is there, the newest log in red4ext/logs says why RED4ext did not load it: an antivirus that removed a file, or a missing Visual C++ runtime."] = "Klasör oradaysa red4ext/logs içindeki en yeni günlük, RED4ext’in onu neden yüklemediğini söyler: bir antivirüs dosyayı silmiş ya da Visual C++ runtime eksik.",
    ["Load a save first. A key can be set only while a game is loaded."] = "Önce bir kayıt yükle. Bir tuş yalnızca oyun yüklüyken ayarlanabilir.",
    ["No key press reached the mod, so nothing changed. If keys do not arrive from this menu, set the key in Cyber Engine Tweaks’ Bindings: it works the same."] = "Moda hiçbir tuş basımı ulaşmadı, bu yüzden bir şey değişmedi. Tuşlar bu menüden ulaşmazsa, tuşu Cyber Engine Tweaks’in tuş atamalarından ayarla: aynı şekilde çalışır.",
    ["Runtime incomplete"] = "Runtime eksik",
    ["Runtime not loaded"] = "Runtime yüklenmedi",
    ["Service not running ({reason})"] = "Servis çalışmıyor ({reason})",
    ["The Runtime’s plugin is loaded, but the conversation service left no trace in this session. launcher.log in red4ext/plugins/AiNpcCyberpunkCode says why: launcher.ini switched off, Node missing, or Node blocked by a security program. Fix that, then restart the game."] = "Runtime’ın eklentisi yüklü, ama konuşma servisi bu oturumda hiçbir iz bırakmadı. red4ext/plugins/AiNpcCyberpunkCode içindeki launcher.log nedenini söyler: launcher.ini kapalı, Node yok ya da Node bir güvenlik programı tarafından engellenmiş. Bunu düzelt, ardından oyunu yeniden başlat.",
    ["The conversation service cannot see this mod’s folder in the game: a mod manager’s virtual folders, or a folder it may not read. Extract the Runtime straight into the Cyberpunk 2077 folder, or start the game from the mod manager that holds the Runtime."] = "Konuşma servisi oyunda bu modun klasörünü göremiyor: bir mod yöneticisinin sanal klasörleri ya da okuma izni olmayan bir klasör. Runtime’ı doğrudan Cyberpunk 2077 klasörüne çıkar veya oyunu Runtime’ı içeren mod yöneticisinden başlat.",
    ["The conversation service was started and never reported back. A security program probably stopped it at once, or Node cannot run on this PC. Allow red4ext/plugins/AiNpcCyberpunkMod/app/node/node.exe in your security program, then restart the game."] = "Konuşma servisi başlatıldı ama hiç geri dönmedi. Büyük olasılıkla bir güvenlik programı hemen durdurdu ya da Node bu bilgisayarda çalışamıyor. Güvenlik programında red4ext/plugins/AiNpcCyberpunkMod/app/node/node.exe dosyasına izin ver, sonra oyunu yeniden başlat.",
    ["Windows would not let the game start the conversation service (error {error}). A security program may be blocking node.exe in red4ext/plugins/AiNpcCyberpunkMod/app/node: allow it, then restart the game."] = "Windows, oyunun konuşma servisini başlatmasına izin vermedi (hata {error}). Bir güvenlik programı red4ext/plugins/AiNpcCyberpunkMod/app/node içindeki node.exe dosyasını engelliyor olabilir: izin ver, ardından oyunu yeniden başlat.",
    ["Add a server address first."] = "Önce bir sunucu adresi ekleyin.",
    ["Asks the server three times who it is and shows whether it is reachable, how long it takes to answer and its version. It sends no speech."] = "Sunucuya üç kez kim olduğunu sorar ve erişilebilir olup olmadığını, yanıt süresini ve sürümünü gösterir. Ses göndermez.",
    ["Connected. The server speaks with {voice}."] = "Bağlandı. Sunucu {voice} sesiyle konuşuyor.",
    ["Custom voices"] = "Özel sesler",
    ["Deletes the saved server address. Remote OmniVoice needs one to speak."] = "Kayıtlı sunucu adresini siler. Uzak OmniVoice'un konuşabilmesi için bir adrese ihtiyacı vardır.",
    ["It answers in {ms} ms."] = "{ms} ms içinde yanıt veriyor.",
    ["Its voice runs on {device}."] = "Sesi {device} üzerinde çalışıyor.",
    ["Loading"] = "Yükleniyor",
    ["Not connected. Replies show as text until the server answers."] = "Bağlı değil. Sunucu yanıt verene kadar yanıtlar metin olarak gösterilir.",
    ["Nothing answered at that address. Check that the server is running, that the address and port are right and that both PCs are on the same network. A server started with its default only listens on its own PC: start it with the listen address 0.0.0.0."] = "Bu adresten yanıt alınamadı. Sunucunun çalıştığını, adres ve port bilgilerinin doğru olduğunu ve iki bilgisayarın da aynı ağda olduğunu kontrol edin. Varsayılan ayarla başlatılan sunucu yalnızca kendi bilgisayarını dinler: onu 0.0.0.0 dinleme adresiyle başlatın.",
    ["Off. OmniVoice runs on this PC."] = "Kapalı. OmniVoice bu bilgisayarda çalışır.",
    ["On, but no server address is saved. OmniVoice cannot speak yet."] = "Açık, ancak kayıtlı bir sunucu adresi yok. OmniVoice henüz konuşamaz.",
    ["On, but no server address is saved. Pocket is used until you add one."] = "Açık, ancak kayıtlı bir sunucu adresi yok. Bir adres ekleyene kadar Pocket kullanılır.",
    ["On, but no server address is saved. The server is not used yet."] = "Açık, ancak kayıtlı bir sunucu adresi yok. Sunucu henüz kullanılmıyor.",
    ["On, but a cloud voice is chosen under Companion voices, so the server is not used."] = "Açık, ancak Yoldaş sesleri altında bulut sesi seçili, bu yüzden sunucu kullanılmıyor.",
    ["On. Waiting for the conversation service."] = "Açık. Konuşma hizmeti bekleniyor.",
    ["Paste address"] = "Adresi yapıştır",
    ["Remote OmniVoice"] = "Uzak OmniVoice",
    ["Render the voices on another PC or graphics card that runs the OmniVoice server, so this PC keeps its frames.\n\nTurn it on, press Apply and add the server address below. The server then speaks for every Pocket or OmniVoice choice under Companion voices; a cloud voice stays as chosen. If it cannot be reached, replies show as text and the mod retries every few seconds."] = "OmniVoice sunucusunu çalıştıran başka bir bilgisayarda veya ekran kartında sesleri işleyin, böylece bu bilgisayar kare hızını korur.\n\nAçın, Uygula’ya basın ve aşağıya sunucu adresini ekleyin. Sunucu, Yoldaş seslerindeki her Pocket veya OmniVoice seçimi için konuşur; bulut sesi seçildiği gibi kalır. Sunucuya ulaşılamazsa yanıtlar metin olarak gösterilir ve mod birkaç saniyede bir yeniden dener.",
    ["Render the OmniVoice voices on another PC or graphics card that runs the OmniVoice server."] = "OmniVoice sunucusunu çalıştıran başka bir bilgisayarda veya ekran kartında OmniVoice seslerini işleyin.",
    ["Render Pocket and OmniVoice voices on another PC or graphics card: the on/off switch, the server address and a connection test. It works whichever of those voices is chosen above."] = "Pocket ve OmniVoice seslerini başka bir bilgisayarda veya ekran kartında işleyin: açma/kapama düğmesi, sunucu adresi ve bağlantı testi. Yukarıda hangisi seçili olursa olsun çalışır.",
    ["Server address"] = "Sunucu adresi",
    ["Something answered, but it is not the OmniVoice server. Check the port."] = "Bir şey yanıt verdi, ancak OmniVoice sunucusu değil. Portu kontrol edin.",
    ["Start the OmniVoice server on the other PC. Its window shows the address to use, for example 192.168.1.20:8765. Copy it, then choose Paste address. It is read from the clipboard once and saved on this computer.\n\nOn the same PC use 127.0.0.1:8765. You can also write address=192.168.1.20:8765 in player-remote-omnivoice.txt in the conversation service folder.\n\nNothing is sent to it until Remote OmniVoice is on and OmniVoice is chosen, or you press Test."] = "OmniVoice sunucusunu diğer bilgisayarda başlatın. Penceresi kullanılacak adresi gösterir, örneğin 192.168.1.20:8765. Kopyalayın, ardından Adresi yapıştır'ı seçin. Adres panodan bir kez okunur ve bu bilgisayara kaydedilir.\n\nAynı bilgisayarda 127.0.0.1:8765 kullanın. Konuşma hizmeti klasöründeki player-remote-omnivoice.txt dosyasına address=192.168.1.20:8765 yazabilirsiniz.\n\nUzak OmniVoice açılıp OmniVoice seçilene ya da Test'e basılana kadar hiçbir şey gönderilmez.",
    ["Status"] = "Durum",
    ["The OmniVoice server cannot be reached. Replies show as text until it answers. The mod asks it again every few seconds."] = "OmniVoice sunucusuna ulaşılamıyor. Yanıt verene kadar yanıtlar metin olarak gösterilir. Mod, sunucuya birkaç saniyede bir yeniden sorar.",
    ["The clipboard does not hold a server address."] = "Pano bir sunucu adresi içermiyor.",
    ["The clipboard is empty. Copy the address first."] = "Pano boş. Önce adresi kopyalayın.",
    ["The port must be a number from 1 to 65535."] = "Port, 1 ile 65535 arasında bir sayı olmalıdır.",
    ["The server address was removed."] = "Sunucu adresi kaldırıldı.",
    ["The server answered but could not load its voice. Its window says why."] = "Sunucu yanıt verdi ancak sesini yükleyemedi. Penceresi nedenini gösterir.",
    ["The server answered but is still loading its voice. Try again in a minute."] = "Sunucu yanıt verdi ama hâlâ sesini yüklüyor. Bir dakika sonra tekrar deneyin.",
    ["The server is another version. Use the server folder and the mod from the same release."] = "Sunucu başka bir sürüm. Sunucu klasörünü ve modu aynı sürümden kullanın.",
    ["The server is ready."] = "Sunucu hazır.",
    ["The server refused the request."] = "Sunucu isteği reddetti.",
    ["The server took too long to answer."] = "Sunucunun yanıtı çok uzun sürdü.",
    ["Use the address only: no user name, no path, no #."] = "Yalnızca adresi girin: kullanıcı adı, yol veya # olmadan.",
    ["Use the address the server window shows, such as 192.168.1.20:8765, without https://."] = "Sunucu penceresinin gösterdiği adresi girin, örneğin 192.168.1.20:8765, https:// olmadan.",
    ["Waiting for the server to answer…"] = "Sunucunun yanıtı bekleniyor…",
    ["Whether the server is in use right now. It is checked when a voice is needed and again every few seconds after a failure, never while you play."] = "Sunucunun şu anda kullanımda olup olmadığı. Bir ses gerektiğinde kontrol edilir, hatadan sonra her birkaç saniyede bir tekrar kontrol edilir, oynarken asla kontrol edilmez.",
    ["Your own character, made in the character editor."] = "Karakter düzenleyicide yaptığın kendi karakterin.",
    ["They join as a copy of the model they were made from. They talk with Mistral, Local AI or Custom; with Convai they talk as an ordinary person."] = "Yapıldığı modelin bir kopyası olarak katılır. Mistral, Local AI veya Özel ile konuşur; Convai ile sıradan bir insan gibi konuşur.",
    ["This character needs Mistral, Local AI or Custom to answer."] = "Bu karakterin yanıt verebilmesi için Mistral, Local AI veya Özel gerekir.",
    ["Build for your game"] = "Oyununa uygun yapı",
    ["Your game is {game} but the Runtime is the one for game {runtime}. Download the Runtime for game {game} from the mod’s Hugging Face page (the main folder is for game 2.5, the game-2.31 folder is for game 2.31) and extract it into the Cyberpunk 2077 folder over this one, then restart the game."] = "Oyunun {game}, ama Runtime {runtime} oyunu için hazırlanmış. {game} oyunu için Runtime'ı modun Hugging Face sayfasından indir (ana klasör 2.5 oyunu için, game-2.31 klasörü 2.31 oyunu için), Cyberpunk 2077 klasörüne mevcut dosyaların üstüne çıkar, ardından oyunu yeniden başlat.",
    ["Your game is {game} but the Scripts are the build for game {scripts}. Download the Scripts for game {game} from the mod’s Nexus Mods page (the main file is for game 2.5, the optional file marked for game 2.31 is for game 2.31) and install them over these, then restart the game."] = "Oyunun {game}, ama Scripts {scripts} oyunu için hazırlanmış. {game} oyunu için Scripts'i modun Nexus Mods sayfasından indir (ana dosya 2.5 oyunu için, 2.31 olarak işaretlenmiş isteğe bağlı dosya 2.31 oyunu için), mevcut dosyaların üstüne kur, ardından oyunu yeniden başlat.",
    ["Your game is {game} but the Scripts and the Runtime are the build for game {scripts}. Download both for game {game}: the Scripts from the mod’s Nexus Mods page, the Runtime from its Hugging Face page (the main folder is for game 2.5, the game-2.31 folder is for game 2.31). Install them over these, then restart the game."] = "Oyunun {game}, ama Scripts ve Runtime {scripts} oyunu için hazırlanmış. {game} oyunu için ikisini de indir: Scripts'i modun Nexus Mods sayfasından, Runtime'ı Hugging Face sayfasından (ana klasör 2.5 oyunu için, game-2.31 klasörü 2.31 oyunu için). Mevcut dosyaların üstüne kur, ardından oyunu yeniden başlat.",
    ["The Scripts are the build for game {scripts} but the Runtime is the build for game {runtime}, and the game version matches neither. Install the Scripts and the Runtime made for the same game as yours (the Scripts from Nexus Mods, the Runtime from Hugging Face), then restart the game."] = "Scripts {scripts} oyunu için hazırlanmış, Runtime {runtime} oyunu için hazırlanmış ve oyun sürümü ikisiyle de eşleşmiyor. Oyunuyla aynı oyun için yapılmış Scripts ve Runtime'ı kur (Scripts Nexus Mods'tan, Runtime Hugging Face'ten), ardından oyunu yeniden başlat.",
    ["The Runtime is for game {other}, yours is {game}. Get the Runtime for {game} from Hugging Face."] = "Runtime {other} oyunu için, senin oyunun {game}. {game} için Runtime'ı Hugging Face'ten al.",
    ["The Scripts are for game {other}, yours is {game}. Get the Scripts for {game} from Nexus Mods."] = "Scripts {other} oyunu için, senin oyunun {game}. {game} için Scripts'i Nexus Mods'tan al.",
    ["This mod is for game {other}, yours is {game}. Get the Scripts and Runtime for {game}."] = "Mod {other} oyunu için, senin oyunun {game}. {game} için Scripts ve Runtime'ı al.",
    ["Scripts are for game {scripts}, Runtime for {runtime}. They must match. See Help in Settings."] = "Scripts {scripts}, Runtime {runtime} için. Eşleşmeli: Ayarlar'daki Yardım'a bak.",
    ["Choose one of the listed microphones."] = "Listelenen mikrofonlardan birini seç.",
    ["Microphone"] = "Mikrofon",
    ["The microphone you chose in Settings ({chosen}) is not connected, so the Windows default input is used: {name}."] = "Ayarlar'da seçtiğin mikrofon ({chosen}) bağlı değil, bu yüzden Windows varsayılan girişi kullanılıyor: {name}.",
    ["The microphone you chose in Settings is not connected, so the Windows default input is used."] = "Ayarlar'da seçtiğin mikrofon bağlı değil, bu yüzden Windows varsayılan girişi kullanılıyor.",
    ["Windows default"] = "Windows varsayılanı",
    ["not connected"] = "bağlı değil",
    ["{name}, chosen in Settings > Voices."] = "{name}, Ayarlar > Sesler'de seçildi.",
    ["{name}, the Windows default input. Settings > Voices > Microphone chooses another."] = "{name}, Windows varsayılan girişi. Başkasını Ayarlar > Sesler > Mikrofon'dan seçebilirsin.",
    ["Gameplay"] = "Oynanış",
    ["Revenge ambushes"] = "İntikam pusuları",
    ["A gang you keep killing may rarely send a small squad after you, with a short threat to shout. A long wait follows each one.\n\nNever in a fight, scene, call, vehicle, indoors, safe zone or while wanted. The threats need Talk to ordinary NPCs."] = "Sürekli öldürdüğün bir çete, nadiren kısa bir tehditle küçük bir ekip gönderebilir. Her birinin ardından uzun bir bekleme gelir.\n\nAsla dövüş, sahne, telefon görüşmesi, araç içi, bina içi, güvenli bölge ya da arananken olmaz. Tehditler için «Sıradan NPC'lerle konuş» gerekir.",
    ["Speak dialogue choices"] = "Diyalog seçeneklerini söyle",
    ["Say a dialogue choice to pick it: its words, a part of them, or its number (\"two\", \"the last one\"). If nothing fits clearly, nothing is picked. No character answers.\n\nPresses the arrow keys and Enter, so the game must be in front. Needs speech recognition on this PC. Headphones work best."] = "Bir diyalog seçeneğini söyleyerek seç: sözcükleri, bir kısmı ya da numarası (\"iki\", \"sondaki\"). Hiçbir şey açıkça uymuyorsa hiçbir şey seçilmez. Hiçbir karakter yanıt vermez.\n\nYön tuşlarına ve Enter'a basar, bu yüzden oyunun ön planda olması gerekir. Bu bilgisayarda konuşma tanıma gerekir. En iyi sonucu kulaklıkla alırsın.",
    ["No option matched. Say its number."] = "Hiçbir seçenekle eşleşmedi. Numarasını söyle.",
    ["Two options fit. Say its number."] = "İki seçenek uyuyor. Numarasını söyle.",
    ["Speaking a choice needs speech recognition on this PC."] = "Bir seçeneği söylemek için bu bilgisayarda konuşma tanıma gerekir.",
    ["AMD’s ROCm PyTorch does not support this card yet."] = "AMD’nin ROCm PyTorch’u bu kartı henüz desteklemiyor.",
    ["Another setup is already running. Wait for it to finish."] = "Başka bir kurulum zaten çalışıyor. Bitmesini bekle.",
    ["Cancelled"] = "İptal edildi",
    ["Cancelling…"] = "İptal ediliyor…",
    ["Checking your card…"] = "Kartın kontrol ediliyor…",
    ["Downloading {done} of {total} MB ({percent}%)"] = "{done} / {total} MB indiriliyor ({percent}%)",
    ["Downloading…"] = "İndiriliyor…",
    ["Experimental. Pocket speaks until it is ready. A local voice never switches to a cloud voice."] = "Deneysel. Pocket hazır olana kadar konuşur. Yerel bir ses hiçbir zaman bulut sesine geçmez.",
    ["Frees about {disk} GB."] = "Yaklaşık {disk} GB yer açar.",
    ["Frees the space it took."] = "Kapladığı alanı geri verir.",
    ["Install"] = "Kur",
    ["Installed"] = "Kuruldu",
    ["Installed. OmniVoice uses it when it starts."] = "Kuruldu. OmniVoice başladığında bunu kullanır.",
    ["It is kept in the mod’s data folder on drive C:."] = "Modun veri klasöründe, C: sürücüsünde tutulur.",
    ["It runs in the background while you play. The game keeps running and nothing else changes."] = "Oynarken arka planda çalışır. Oyun çalışmaya devam eder ve başka hiçbir şey değişmez.",
    ["It takes about {disk} GB on drive C: in the mod’s data folder."] = "Modun veri klasöründe, C: sürücüsünde yaklaşık {disk} GB yer kaplar.",
    ["MIOpen convolutions (AMD)"] = "MIOpen evrişimleri (AMD)",
    ["Not available on this PC. It needs an AMD Radeon card and the OmniVoice pack."] = "Bu PC’de kullanılamaz. AMD Radeon kartı ve OmniVoice paketi gerekir.",
    ["OmniVoice for AMD"] = "AMD için OmniVoice",
    ["OmniVoice on AMD: set up first"] = "AMD’de OmniVoice: önce ayarla",
    ["OmniVoice then no longer starts on this card until it is set up again."] = "Bu karttan sonra OmniVoice, yeniden ayarlanana kadar başlamaz.",
    ["On: AMD’s MIOpen runs the convolutions, with MIOPEN_FIND_MODE=2 and MIOPEN_FIND_ENFORCE=1. Off: PyTorch’s own convolutions. Which is faster depends on your card and driver: if voices are slow or stop part-way, try the other one. AMD cards only. OmniVoice restarts with the new choice when it is idle."] = "Açık: AMD’nin MIOpen’ı evrişimleri çalıştırır, MIOPEN_FIND_MODE=2 ve MIOPEN_FIND_ENFORCE=1 ile. Kapalı: PyTorch’un kendi evrişimleri. Hangisinin daha hızlı olduğu kartına ve sürücüne bağlıdır: sesler yavaşsa ya da yarıda kesiliyorsa diğerini dene. Yalnızca AMD kartlarda. OmniVoice boştayken yeni seçimle yeniden başlar.",
    ["Own Python"] = "Kendi Python’un",
    ["Ready"] = "Hazır",
    ["Ready. OmniVoice runs on {card} with AMD’s ROCm."] = "Hazır. OmniVoice, AMD’nin ROCm’uyla {card} üzerinde çalışır.",
    ["Reinstall"] = "Yeniden kur",
    ["Remove AMD setup"] = "AMD kurulumunu kaldır",
    ["Removing the AMD setup…"] = "AMD kurulumu kaldırılıyor…",
    ["Run OmniVoice on your AMD Radeon card with AMD’s ROCm: one download, set up from here."] = "OmniVoice’u AMD Radeon kartında AMD’nin ROCm’uyla çalıştır: tek bir indirme, buradan ayarla.",
    ["Set up OmniVoice for AMD"] = "OmniVoice’u AMD için ayarla",
    ["Starting the AMD setup…"] = "AMD kurulumu başlatılıyor…",
    ["Testing it on your card…"] = "Kartında deneniyor…",
    ["The AMD setup was removed."] = "AMD kurulumu kaldırıldı.",
    ["The OmniVoice pack is not installed. Install it first."] = "OmniVoice paketi kurulu değil. Önce onu kur.",
    ["The conversation service is not running. Restart the game."] = "Konuşma servisi çalışmıyor. Oyunu yeniden başlat.",
    ["The download did not finish. Check your connection and try again."] = "İndirme tamamlanmadı. Bağlantını kontrol edip yeniden dene.",
    ["The download is not ready yet in this version of the mod."] = "İndirme bu mod sürümünde henüz hazır değil.",
    ["The downloaded files did not check out. Try again."] = "İndirilen dosyalar kontrolden geçemedi. Yeniden dene.",
    ["The files could not be unpacked. Try again."] = "Dosyalar açılamadı. Yeniden dene.",
    ["The setup did not finish. Try again."] = "Kurulum tamamlanmadı. Yeniden dene.",
    ["The setup did not pass the test on your card, so OmniVoice cannot use it."] = "Kurulum kartında testi geçemedi, bu yüzden OmniVoice onu kullanamaz.",
    ["The setup is installed but did not pass the test on your card. Choose Reinstall."] = "Kurulum yüklü ama kartında testi geçemedi. Yeniden kur seçeneğini seç.",
    ["There is not enough free space on drive C:. Free some up and try again."] = "C: sürücüsünde yeterli boş alan yok. Biraz yer aç ve yeniden dene.",
    ["This PC has no AMD Radeon card this setup can use."] = "Bu PC’de bu kurulumun kullanabileceği bir AMD Radeon kartı yok.",
    ["Unpacking…"] = "Açılıyor…",
    ["Your own Python (omni-python.txt) is used instead. Delete that file to use this setup."] = "Bunun yerine kendi Python’un (omni-python.txt) kullanılır. Bu kurulumu kullanmak için o dosyayı sil.",
    ["your AMD card"] = "AMD kartın",
    ["{voice} · AMD: set up first"] = "{voice} · AMD: önce ayarla",
    ["The AMD setup (Settings > Voices > OmniVoice for AMD) runs OmniVoice with ROCm on {card}. Experimental."] = "AMD kurulumu (Ayarlar > Sesler > AMD için OmniVoice) OmniVoice’u {card} üzerinde ROCm ile çalıştırıyor. Deneysel.",
    ["The AMD setup was not used: {reason}. Choose Reinstall in Settings > Voices > OmniVoice for AMD. Until then Pocket speaks."] = "AMD kurulumu kullanılmadı: {reason}. Ayarlar > Sesler > AMD için OmniVoice bölümünde Yeniden kur’u seç. O zamana kadar Pocket konuşur.",
    ["Borrow eddies from your characters, lend them eddies and pay each other back, by talking. Each character has money of their own, as their story has it, and decides by how they feel about you. Now and then they ask you for a loan.\n\nEddies change hands as soon as a character agrees, and only with your own characters (party, invited visitors, housemates). The game’s own characters only talk about it. Off by default."] = "Karakterlerinle konuşarak eddies ödünç al, onlara ver ve geri öde. Her karakterin kendi parası vardır ve sana karşı hissine göre karar verir. Zaman zaman senden borç isterler.\n\nBir karakter kabul eder etmez Eddies el değiştirir ve bu, yalnızca kendi karakterlerinle (parti, davetliler, ev arkadaşları) olur. Oyunun karakterleri bunu yalnızca konuşur. Varsayılan olarak kapalı.",
    ["Eddies with characters"] = "Karakterlerle eddies",
    ["The eddies could not be moved."] = "Eddies taşınamadı.",
    ["You do not have enough eddies for that."] = "Bunun için yeterli eddies yok.",
    ["{name} is no longer with you, so no eddies moved."] = "{name} artık seninle değil, bu yüzden hiçbir eddies taşınmadı.",
    ["Add"] = "Ekle",
    ["Add to favorites"] = "Favorilere ekle",
    ["Adds the last entry you were on in the list to your favorites, or takes it out again."] = "Listede en son bulunduğun girişi favorilerine ekler veya tekrar çıkarır.",
    ["Favorites are listed first, on page 1, and their name starts with a *. Updates never touch them."] = "Favoriler 1. sayfada en başta listelenir ve adları * ile başlar. Güncellemeler onlara asla dokunmaz.",
    ["Move onto an entry in the list first, then press the button."] = "Önce listedeki bir girişin üzerine gel, sonra düğmeye bas.",
    ["One download of about {size} GB."] = "Tek bir indirme, yaklaşık {size} GB.",
    ["One download."] = "Tek bir indirme.",
    ["Remove from favorites"] = "Favorilerden çıkar",
    ["Set up OmniVoice on your AMD Radeon card with one download, and choose how it runs."] = "OmniVoice’u AMD Radeon kartında tek bir indirmeyle ayarla ve nasıl çalışacağını seç.",
    ["That entry cannot be a favorite."] = "Bu giriş favori olamaz.",
    ["This menu cannot tell which entry you are on, and has no Search box."] = "Bu menü hangi girişte olduğunu anlayamıyor ve Arama kutusu yok.",
    ["Type a name in the Search box first, then press the button."] = "Önce Arama kutusuna bir ad yaz, sonra düğmeye bas.",
    ["Type a name in the Search box, then press this to add the first entry listed to your favorites, or to take it out again."] = "Arama kutusuna bir ad yaz, sonra bu düğmeye basarak listede ilk görünen girişi favorilerine ekle ya da tekrar çıkar.",
    ["You have too many favorites. Remove one first."] = "Çok fazla favorin var. Önce birini çıkar.",
    ["Your AMD Radeon card ({card}) can run OmniVoice. Set it up in Settings > Voices > OmniVoice for AMD: one download, then it starts by itself."] = "AMD Radeon kartın ({card}) OmniVoice’u çalıştırabilir. Ayarlar > Sesler > AMD için OmniVoice bölümünden ayarla: tek bir indirme, sonra kendi kendine başlar.",
    ["Your AMD Radeon card can run OmniVoice. Set it up in Settings > Voices > OmniVoice for AMD: one download, then it starts by itself. Until then Pocket speaks."] = "AMD Radeon kartın OmniVoice’u çalıştırabilir. Ayarlar > Sesler > AMD için OmniVoice bölümünden ayarla: tek bir indirme, sonra kendi kendine başlar. O zamana kadar Pocket konuşur.",
    ["Your favorites could not be saved, so they last only until the game closes."] = "Favorilerin kaydedilemedi, bu yüzden yalnızca oyun kapanana kadar kalacaklar.",
    ["{count} matching characters"] = "{count} eşleşen karakter",
    ["{name} is no longer a favorite."] = "{name} artık favori değil.",
    ["{name} is now a favorite. Favorites are listed first."] = "{name} artık favori. Favoriler en başta listelenir.",
    ["A saved party holds {count} characters, so the rest were left out."] = "Kayıtlı bir ekip {count} karakter alabilir, bu yüzden geri kalanlar dışarıda bırakıldı.",
    ["Already with you: {names}."] = "Zaten seninle: {names}.",
    ["Another saved party already has that name."] = "Kayıtlı başka bir ekip bu adı zaten kullanıyor.",
    ["Could not invite: {names}."] = "Davet edilemedi: {names}.",
    ["Deletes this saved party. The characters in your party now are not touched."] = "Bu kayıtlı ekibi siler. Şu an ekibinde olan karakterler etkilenmez.",
    ["Invites the characters of this party to your side: {names}.\n\nIt adds to your party and dismisses nobody. A character who is already with you is not invited twice. Anyone who cannot come is named, with the reason."] = "Bu ekibin karakterlerini yanına davet eder: {names}.\n\nEkibine eklenirler, kimse çıkarılmaz. Zaten seninle olan bir karakter ikinci kez davet edilmez. Gelemeyenler nedenleriyle birlikte belirtilir.",
    ["Parties"] = "Ekipler",
    ["Party"] = "Ekip",
    ["Press Delete again to delete {name}."] = "{name} karakterini silmek için Sil düğmesine tekrar bas.",
    ["Press again"] = "Tekrar bas",
    ["Press again to delete this saved party. Anything else cancels."] = "Bu kayıtlı ekibi silmek için tekrar bas. Başka herhangi bir işlem iptal eder.",
    ["Rename"] = "Yeniden adlandır",
    ["Rename party"] = "Ekibi yeniden adlandır",
    ["Renamed to {name}."] = "Adı {name} olarak değiştirildi.",
    ["Replaces the characters of this saved party with the ones in your party now."] = "Bu kayıtlı ekibin karakterlerini, şu an ekibinde olanlarla değiştirir.",
    ["Save current party"] = "Mevcut ekibi kaydet",
    ["Saved as {name}. Press Spawn party under it to invite them again."] = "{name} olarak kaydedildi. Onları yeniden davet etmek için altındaki Ekibi davet et düğmesine bas.",
    ["Saved party: {name}"] = "Kayıtlı ekip: {name}",
    ["Saves the characters in your party now, copies and your own characters included, as a party you can invite again with one press. It is named Party 1, Party 2 and so on, and appears below.\n\nYou keep up to {count} saved parties."] = "Şu an ekibinde olan karakterleri, kopyalar ve kendi karakterlerin dahil, tek dokunuşla yeniden davet edebileceğin bir ekip olarak kaydeder. Adı Ekip 1, Ekip 2 vb. olur ve aşağıda görünür.\n\nEn fazla {count} kayıtlı ekip tutabilirsin.",
    ["Spawn"] = "Davet et",
    ["Spawn party"] = "Ekibi davet et",
    ["That party no longer exists."] = "Bu ekip artık yok.",
    ["The characters of this party: {names}."] = "Bu ekibin karakterleri: {names}.",
    ["The party could not be saved."] = "Ekip kaydedilemedi.",
    ["This menu has no text box, so the party keeps its name. Mod Configuration Menu has one: type the name in its Search box."] = "Bu menüde metin kutusu yok, bu yüzden ekip adını korur. Mod Configuration Menu'de bir tane var: adı onun arama kutusuna yaz.",
    ["Type the new name in the Search box at the top (Mod Configuration Menu), then press Rename. Native Settings UI has no text box, so a party keeps its name there."] = "Yeni adı üstteki arama kutusuna (Mod Configuration Menu) yaz, sonra Yeniden adlandır düğmesine bas. Native Settings UI'de metin kutusu yok, orada ekip adını korur.",
    ["Type the new name in the Search box first, then press Rename."] = "Önce yeni adı arama kutusuna yaz, sonra Yeniden adlandır düğmesine bas.",
    ["Update"] = "Güncelle",
    ["Update with current party"] = "Mevcut ekiple güncelle",
    ["You can keep {count} saved parties. Delete one first."] = "{count} kayıtlı ekip tutabilirsin. Önce birini sil.",
    ["Your party is empty. Invite someone first."] = "Ekibin boş. Önce birini davet et.",
    ["Your saved parties could not be written to disk, so they last only until the game closes."] = "Kayıtlı ekipler diske yazılamadı, bu yüzden yalnızca oyun kapanana kadar kalacaklar.",
    ["that character model is unavailable"] = "karakter modeli kullanılamıyor",
    ["the invitation was refused"] = "davet reddedildi",
    ["{name} ({count})"] = "{name} ({count})",
    ["{name} ({reason})"] = "{name} ({reason})",
    ["{name} deleted."] = "{name} silindi.",
    ["{name} has nobody to invite."] = "{name} davet edecek kimse yok.",
    ["{name} now has the characters of your party."] = "{name} artık ekibinin karakterlerine sahip.",
    ["{party}: inviting {names}."] = "{party}: {names} davet ediliyor.",
}
